class Solution {
public:
    vector<int> findMode(TreeNode* root) {
        vector<int> result;
        int currVal = 0;
        int currCount = 0;
        int maxCount = 0;
        TreeNode* prev = nullptr;
        TreeNode* curr = root;

        while (curr) {
            if (curr->left == nullptr) {
                if (prev && prev->val == curr->val) {
                    currCount++;
                } else {
                    currVal = curr->val;
                    currCount = 1;
                }
                if (currCount > maxCount) {
                    maxCount = currCount;
                    result.clear();
                    result.push_back(currVal);
                } else if (currCount == maxCount) {
                    result.push_back(currVal);
                }
                prev = curr;
                curr = curr->right;
            } else {
                TreeNode* pred = curr->left;
                while (pred->right && pred->right != curr) {
                    pred = pred->right;
                }
                if (pred->right == nullptr) {
                    pred->right = curr;
                    curr = curr->left;
                } else {
                    pred->right = nullptr;
                    if (prev && prev->val == curr->val) {
                        currCount++;
                    } else {
                        currVal = curr->val;
                        currCount = 1;
                    }
                    if (currCount > maxCount) {
                        maxCount = currCount;
                        result.clear();
                        result.push_back(currVal);
                    } else if (currCount == maxCount) {
                        result.push_back(currVal);
                    }
                    prev = curr;
                    curr = curr->right;
                }
            }
        }

        return result;
    }
};
